/* tPair(en,id): teks bilingual inline untuk template literal — fallback aman ke EN */
function tPair(en,id){return currentLang==='id'?(id!==undefined&&id!==''?id:en):en;}
function applyStaticI18n(){
 document.querySelectorAll('[data-i18n]').forEach(el=>{if(el.classList.contains('footer-slink')&&el.querySelector('svg')){const svg=el.querySelector('svg').outerHTML;el.innerHTML=svg+t(el.dataset.i18n)}else el.innerHTML=t(el.dataset.i18n)});
 document.querySelectorAll('[data-i18n-attr]').forEach(el=>{const[k,a]=el.dataset.i18nAttr.split('|');el.setAttribute(a,t(k))});
 document.querySelectorAll('[data-i18n-ph]').forEach(el=>{el.placeholder=t(el.dataset.i18nPh)});
 document.documentElement.lang=currentLang;
}
function t(key){const d=T[currentLang]||T.en;return d[key]||T.en[key]||key;}
function setLang(lang){currentLang=(lang==='id')?'id':'en';localStorage.setItem(LANG_KEY,currentLang);applyStaticI18n();document.querySelectorAll('.lang-btn').forEach(b=>b.classList.toggle('active',b.dataset.lang===currentLang));document.dispatchEvent(new CustomEvent('toba:langchange'));}
document.addEventListener('DOMContentLoaded',()=>{applyStaticI18n();document.querySelectorAll('.lang-btn').forEach(b=>b.classList.toggle('active',b.dataset.lang===currentLang));document.getElementById('langSwitch')?.addEventListener('click',e=>{const b=e.target.closest('.lang-btn');if(b)setLang(b.dataset.lang)})});

/* =====================================================================
   TOBI SHORT GREETINGS (MASTER PROMPT Part 1.3)
   Greeting pendek 3-7 kata untuk balloon mascot — variasi acak,
   tidak berulang berturut-turut, per bahasa aktif.
   ===================================================================== */
const TOBI_GREETINGS = {
  /* Greeting singkat 1-3 kata (di luar emoji) + aksi opsional.
     Greeting dengan aksi: klik balloon - buka chatbot & jalankan aksi
     (mis. 'emoji' = langsung mulai permainan tebak emoji). */
  id: [
    'Udah makan?','Mau pantun?','Mau quiz?','Tebak emoji yuk!',
    'Haii, baller!','Apa kabar?','Mau main?'
  ],
  en: [
    'Eaten yet?','Want a rhyme?','Quick quiz?','Emoji guessing!',
    'Hey, baller!','How are you?','Wanna play?'
  ],
  /* aksi per index (sinkron dgn daftar di atas) — hanya tebak emoji yg auto-start */
  act: { 3: 'emoji' }
};
let tobiGreetLast = null;
document.addEventListener('toba:tobiGreet', e => {
  const lang = (document.documentElement.lang === 'en') ? 'en' : 'id';
  const list = TOBI_GREETINGS[lang];
  let s = Math.floor(Math.random() * list.length);
  if (list.length > 1 && s === tobiGreetLast) s = (s + 1) % list.length;
  tobiGreetLast = s;
  /* detail.act: aksi greeting utk balloon klikable di script.js */
  if (e.detail){
    e.detail.act = TOBI_GREETINGS.act && TOBI_GREETINGS.act[s] ? TOBI_GREETINGS.act[s] : null;
    e.detail.text = list[s];
  }
  if (e.detail && typeof e.detail.reply === 'function') e.detail.reply(list[s], s, e.detail.act);
});
